// Runs the compiled program (target/deploy/snark_claim.so) in Mollusk together
// with the real SPL Token program. Claims use the vectors generated by the
// TypeScript auction engine, so this also checks that an allocation list the
// watcher produces can be claimed on chain.
//
//   SBF_OUT_DIR=$PWD/target/deploy cargo test --features test-sbf --test claim_flow

#![cfg(feature = "test-sbf")]

use std::collections::HashMap;

use anchor_lang::{prelude::Pubkey, AccountDeserialize, InstructionData, ToAccountMetas};
use anchor_lang::solana_program::instruction::{AccountMeta, Instruction};
use mollusk_svm::{program::keyed_account_for_system_program, result::ProgramResult, Mollusk, MolluskContext};
use mollusk_svm_programs_token::token;
use solana_account::Account;
use solana_program_pack::Pack;
use spl_token::{solana_program::program_option::COption, state::{Account as TokenState, AccountState, Mint}};

const SUPPLY: u64 = 20_000_000;
const ERR_BASE: u32 = 6000; // Anchor custom errors start here, in ClaimError order

struct Vector { claimer: Pubkey, salt: [u8; 16], commitment: [u8; 32], tokens: u64, proof: Vec<[u8; 32]> }

fn hex(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).unwrap()).collect()
}

fn vectors() -> ([u8; 32], Vec<Vector>) {
    let v: serde_json::Value = serde_json::from_str(include_str!("fixtures/merkle_vectors.json")).unwrap();
    let h32 = |x: &serde_json::Value| -> [u8; 32] { hex(x.as_str().unwrap()).try_into().unwrap() };
    let claims = v["claims"].as_array().unwrap().iter().map(|c| Vector {
        claimer: Pubkey::new_from_array(h32(&c["claim_pubkey"])),
        salt: hex(c["salt"].as_str().unwrap()).try_into().unwrap(),
        commitment: h32(&c["commitment"]),
        tokens: c["tokens"].as_str().unwrap().parse().unwrap(),
        proof: c["proof"].as_array().unwrap().iter().map(h32).collect(),
    });
    (h32(&v["root"]), claims.collect())
}

struct Env { ctx: MolluskContext<HashMap<Pubkey, Account>>, creator: Pubkey, relayer: Pubkey, mint: Pubkey, creator_token: Pubkey }

impl Env {
    fn new() -> Self {
        let mut mollusk = Mollusk::new(&snark_claim::id(), "snark_claim");
        token::add_program(&mut mollusk);
        let (creator, relayer, mint, creator_token) = (Pubkey::new_unique(), Pubkey::new_unique(), Pubkey::new_unique(), Pubkey::new_unique());
        let mut store: HashMap<Pubkey, Account> = HashMap::new();
        let wallet = Account { lamports: 10_000_000_000, ..Account::default() };
        store.insert(creator, wallet.clone());
        store.insert(relayer, wallet);
        store.insert(mint, token::create_account_for_mint(Mint {
            mint_authority: COption::Some(creator), supply: SUPPLY * 2, decimals: 6, is_initialized: true, freeze_authority: COption::None,
        }));
        store.insert(creator_token, token_account(mint, creator, SUPPLY * 2));
        let (sys_id, sys) = keyed_account_for_system_program();
        store.insert(sys_id, sys);
        let (tok_id, tok) = token::keyed_account();
        store.insert(tok_id, tok);
        Env { ctx: mollusk.with_context(store), creator, relayer, mint, creator_token }
    }

    fn run(&self, ix: Instruction) -> ProgramResult {
        self.ctx.process_instruction(&ix).program_result
    }

    fn account(&self, key: &Pubkey) -> Account {
        self.ctx.account_store.borrow().get(key).cloned().unwrap_or_default()
    }

    fn token_balance(&self, key: &Pubkey) -> u64 {
        TokenState::unpack(&self.account(key).data).unwrap().amount
    }

    fn launch_state(&self, launch: &Pubkey) -> snark_claim::Launch {
        snark_claim::Launch::try_deserialize(&mut &self.account(launch).data[..]).unwrap()
    }

    fn add_token_account(&self, owner: Pubkey) -> Pubkey {
        let key = Pubkey::new_unique();
        self.ctx.account_store.borrow_mut().insert(key, token_account(self.mint, owner, 0));
        key
    }
}

fn token_account(mint: Pubkey, owner: Pubkey, amount: u64) -> Account {
    token::create_account_for_token_account(TokenState {
        mint, owner, amount, delegate: COption::None, state: AccountState::Initialized,
        is_native: COption::None, delegated_amount: 0, close_authority: COption::None,
    })
}

fn pdas(creator: &Pubkey, launch_id: u64) -> (Pubkey, Pubkey) {
    let (launch, _) = Pubkey::find_program_address(&[b"launch", creator.as_ref(), &launch_id.to_le_bytes()], &snark_claim::id());
    let (vault, _) = Pubkey::find_program_address(&[b"vault", launch.as_ref()], &snark_claim::id());
    (launch, vault)
}

fn create_launch(env: &Env, launch_id: u64) -> Instruction {
    let (launch, vault) = pdas(&env.creator, launch_id);
    Instruction::new_with_bytes(
        snark_claim::id(),
        &snark_claim::instruction::CreateLaunch { launch_id, supply: SUPPLY }.data(),
        snark_claim::accounts::CreateLaunch {
            creator: env.creator, mint: env.mint, creator_token: env.creator_token, launch, vault,
            token_program: token::ID, system_program: anchor_lang::system_program::ID,
        }.to_account_metas(None),
    )
}

fn set_root(env: &Env, launch_id: u64, signer: Pubkey, root: [u8; 32], allocated: u64) -> Instruction {
    let (launch, _) = pdas(&env.creator, launch_id);
    Instruction::new_with_bytes(
        snark_claim::id(),
        &snark_claim::instruction::SetRoot { root, allocated }.data(),
        snark_claim::accounts::SetRoot { creator: signer, launch }.to_account_metas(None),
    )
}

fn claim(env: &Env, launch_id: u64, v: &Vector, claimer: Pubkey, tokens: u64, recipient: Pubkey) -> Instruction {
    let (launch, vault) = pdas(&env.creator, launch_id);
    let (receipt, _) = Pubkey::find_program_address(&[b"claimed", launch.as_ref(), &v.commitment], &snark_claim::id());
    Instruction::new_with_bytes(
        snark_claim::id(),
        &snark_claim::instruction::Claim { commitment: v.commitment, salt: v.salt, tokens, proof: v.proof.clone() }.data(),
        snark_claim::accounts::Claim {
            payer: env.relayer, claimer, launch, vault, recipient_token: recipient, receipt,
            token_program: token::ID, system_program: anchor_lang::system_program::ID,
        }.to_account_metas(None),
    )
}

fn withdraw_unsold(env: &Env, launch_id: u64) -> Instruction {
    let (launch, vault) = pdas(&env.creator, launch_id);
    Instruction::new_with_bytes(
        snark_claim::id(),
        &snark_claim::instruction::WithdrawUnsold {}.data(),
        snark_claim::accounts::WithdrawUnsold {
            creator: env.creator, launch, vault, creator_token: env.creator_token, token_program: token::ID,
        }.to_account_metas(None),
    )
}

fn custom(code: u32) -> ProgramResult {
    ProgramResult::Failure(anchor_lang::solana_program::program_error::ProgramError::Custom(code))
}

fn launched(allocated_override: Option<u64>) -> (Env, [u8; 32], Vec<Vector>, u64) {
    let env = Env::new();
    let (root, claims) = vectors();
    let allocated = allocated_override.unwrap_or(claims.iter().map(|c| c.tokens).sum());
    assert_eq!(env.run(create_launch(&env, 1)), ProgramResult::Success);
    assert_eq!(env.run(set_root(&env, 1, env.creator, root, allocated)), ProgramResult::Success);
    (env, root, claims, allocated)
}

#[test]
fn every_allocation_claims_once_and_the_books_balance() {
    let (env, _, claims, allocated) = launched(None);
    let (launch, vault) = pdas(&env.creator, 1);
    for v in &claims {
        let to = env.add_token_account(v.claimer);
        assert_eq!(env.run(claim(&env, 1, v, v.claimer, v.tokens, to)), ProgramResult::Success);
        assert_eq!(env.token_balance(&to), v.tokens);
        let again = env.add_token_account(v.claimer);
        assert!(env.run(claim(&env, 1, v, v.claimer, v.tokens, again)).is_err(), "a second claim must fail");
        assert_eq!(env.token_balance(&again), 0);
    }
    assert_eq!(env.launch_state(&launch).claimed, allocated);
    assert_eq!(env.token_balance(&vault), SUPPLY - allocated);
}

#[test]
fn claims_need_the_committed_key_and_the_exact_amount() {
    let (env, _, claims, _) = launched(None);
    let v = &claims[0];
    let to = env.add_token_account(v.claimer);
    assert_eq!(env.run(claim(&env, 1, v, claims[1].claimer, v.tokens, to)), custom(ERR_BASE + 5), "wrong claim key");
    assert_eq!(env.run(claim(&env, 1, v, v.claimer, v.tokens + 1, to)), custom(ERR_BASE + 6), "tampered amount");
    let mut unsigned = claim(&env, 1, v, v.claimer, v.tokens, to);
    unsigned.accounts[1] = AccountMeta::new_readonly(v.claimer, false);
    assert!(env.run(unsigned).is_err(), "the claim key must sign");
    assert_eq!(env.token_balance(&to), 0);
    assert_eq!(env.run(claim(&env, 1, v, v.claimer, v.tokens, to)), ProgramResult::Success);
}

#[test]
fn the_root_is_set_once_by_the_creator_before_any_claim() {
    let env = Env::new();
    let (root, claims) = vectors();
    assert_eq!(env.run(create_launch(&env, 7)), ProgramResult::Success);
    let to = env.add_token_account(claims[0].claimer);
    assert_eq!(env.run(claim(&env, 7, &claims[0], claims[0].claimer, claims[0].tokens, to)), custom(ERR_BASE + 3), "no root yet");
    assert!(env.run(set_root(&env, 7, env.relayer, root, 1)).is_err(), "only the creator sets the root");
    assert_eq!(env.run(set_root(&env, 7, env.creator, [0; 32], 1)), custom(ERR_BASE + 2), "empty root");
    assert_eq!(env.run(set_root(&env, 7, env.creator, root, SUPPLY + 1)), custom(ERR_BASE + 4), "more than the supply");
    assert_eq!(env.run(set_root(&env, 7, env.creator, root, SUPPLY)), ProgramResult::Success);
    assert_eq!(env.run(set_root(&env, 7, env.creator, root, SUPPLY)), custom(ERR_BASE + 1), "already set");
}

#[test]
fn claims_cannot_exceed_the_allocated_total() {
    // A root whose declared total is less than its leaves sum: the last claim must stop.
    let (env, _, claims, allocated) = launched(Some(vectors().1.iter().map(|c| c.tokens).sum::<u64>() - 1));
    let (launch, _) = pdas(&env.creator, 1);
    let (last, rest) = claims.split_last().unwrap();
    for v in rest {
        assert_eq!(env.run(claim(&env, 1, v, v.claimer, v.tokens, env.add_token_account(v.claimer))), ProgramResult::Success);
    }
    assert_eq!(env.run(claim(&env, 1, last, last.claimer, last.tokens, env.add_token_account(last.claimer))), custom(ERR_BASE + 4));
    assert!(env.launch_state(&launch).claimed <= allocated);
}

#[test]
fn the_creator_withdraws_unsold_tokens_once() {
    let (env, _, _, allocated) = launched(None);
    let before = env.token_balance(&env.creator_token);
    assert_eq!(env.run(withdraw_unsold(&env, 1)), ProgramResult::Success);
    assert_eq!(env.token_balance(&env.creator_token), before + SUPPLY - allocated);
    assert_eq!(env.run(withdraw_unsold(&env, 1)), custom(ERR_BASE + 7));
}
